import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import AdminDepartments from './admin/AdminDepartments';
import AdminUsers from './admin/AdminUsers';
import AdminPapers from './admin/AdminPapers';

const TABS = [
  { key:'departments', label:'🏢 Departments' },
  { key:'users',       label:'👥 Users' },
  { key:'papers',      label:'📄 Papers' },
];

export default function AdminDashboard() {
  const { user } = useAuth();
  const loc = useLocation();
  const [tab, setTab] = useState('departments');

  useEffect(() => {
    // If coming back from capture, set tab to papers
    if (loc.state?.tab) {
      setTab(loc.state.tab);
    }
  }, [loc.state]);

  return (
    <div>
      <Navbar title="QR Office Admin" greeting={`Welcome, ${user?.username}! You are Administrator`} notifCount={0} />
      <div className="tabs">
        {TABS.map(t => (
          <button key={t.key} className={`tab ${tab===t.key?'active':''}`} onClick={() => setTab(t.key)}>
            {t.label}
          </button>
        ))}
      </div>
      <div className="page">
        {tab === 'departments' && <AdminDepartments />}
        {tab === 'users'       && <AdminUsers />}
        {tab === 'papers'      && <AdminPapers />}
      </div>
    </div>
  );
}
